def _validate_request_payload(data):
    """Validate the shape required by ``process``.

    The request payload must be a dictionary whose keys are all strings.
    Validation is kept separate from request processing so that every request
    follows the same checks before it is passed downstream.
    """
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    for key in data:
        if not isinstance(key, str):
            raise TypeError("data keys must be strings")


def handle_request(data):
    """Validate an incoming API request payload before processing it.

    Args:
        data: A dictionary payload with string keys.

    Raises:
        TypeError: If data is not a dictionary or contains non-string keys.
    """
    _validate_request_payload(data)
    return process(data)

